// JUDGMENT-CALL THRESHOLD, not brief-specified - flagged prominently, see the trigger node's own
// notes. engagementScore (health-scoring.workflow.json) maxes at 100 (40 tenure + 30 locations +
// 30 tier); CHURN_RISK_THRESHOLD picks the bottom quarter as 'at risk' - a company that's both new
// (low tenure) AND single-location AND Gold-tier would score right around here, so this also
// catches legitimately-small-but-fine accounts, not just genuinely disengaged ones. That's a real
// false-positive risk worth a human's second look, which is exactly why this workflow drafts and
// alerts rather than acting - same reasoning as every other draft-and-approve workflow here.
const CHURN_RISK_THRESHOLD = 25;
// Re-flag the same still-at-risk company at most once every COOLDOWN_DAYS - prevents a company that
// stays low every single week from generating a fresh draft every single week forever.
const COOLDOWN_DAYS = 30;
const MS_PER_DAY = 86400000;

function asArray(item) {
  const json = item.json;
  if (Array.isArray(json)) return json;
  if (json && json.data && Array.isArray(json.data.companies)) return json.data.companies;
  if (json && Array.isArray(json.companies)) return json.companies;
  return [];
}

const now = new Date();
const atRisk = [];

for (const company of $input.all().flatMap(asArray)) {
  if (company.engagementScore == null || company.engagementScore >= CHURN_RISK_THRESHOLD) continue;
  const lastSent = company.churnWinbackSentAt;
  if (lastSent) {
    const daysSince = (now - new Date(lastSent)) / MS_PER_DAY;
    if (daysSince < COOLDOWN_DAYS) continue;
  }
  atRisk.push({ ...company, winbackAttempt: (company.churnWinbackAttemptCount || 0) + 1 });
}

return atRisk.map((c) => ({ json: c }));

const body = $input.first().json;
const textBlock = (body.content || []).find((b) => b.type === 'text');
if (!textBlock) throw new Error('Claude response had no text content block.');
return [{ json: { draftText: textBlock.text } }];
